import pandas as pd
from typing import List, Dict
import re


def task_func(df: pd.DataFrame, column: str) ->pd.Series:

    def extract_matches(x):
        return re.findall('([a-fA-F\\d]{32})', x)
    matches = df[column].apply(extract_matches)
    flattened_matches = [item for sublist in matches for item in sublist]
    counts = pd.Series(flattened_matches).value_counts()
    return counts

