import pandas as pd
from typing import List, Tuple


def task_func(df: pd.DataFrame, column: str) ->pd.Series:
    pattern = '([a-fA-F\\d]{32})'
    matches = df[column].str.findall(pattern)
    unique_matches = set()
    for match in matches.values.flatten():
        if match:
            unique_matches.add(match[0])
    counts = {match: sum(1 for m in matches.values.flatten() if m == match) for
        match in unique_matches}
    return pd.Series(counts).sort_values(ascending=False)

