import datetime
from zoneinfo import ZoneInfo


def task_func(date_str: str, from_tz: str, to_tz: str) ->str:
    try:
        date_obj = datetime.datetime.strptime(date_str, '%Y-%m-%d %H:%M:%S'
            ).replace(tzinfo=ZoneInfo(from_tz))
        converted_date = date_obj.astimezone(ZoneInfo(to_tz))
        return converted_date.strftime('%Y-%m-%d %H:%M:%S')
    except ValueError:
        raise ValueError('Invalid date format provided.')

