import pytz
from datetime import datetime


def task_func(date_str, from_tz, to_tz):

    def parse_date(date_string):
        return datetime.strptime(date_string, '%Y-%m-%d %H:%M:%S')

    def get_timezone(timezone_name):
        return pytz.timezone(timezone_name)
    parsed_date = parse_date(date_str)
    from_time = get_timezone(from_tz)
    to_time = get_timezone(to_tz)
    aware_date = from_time.localize(parsed_date)
    converted_date = aware_date.astimezone(to_time)
    return converted_date.strftime('%Y-%m-%d %H:%M:%S')

