        raise TypeError('Input must be a dictionary')
    employee_ids = []
    for prefix, count in dict1.items():
        if not isinstance(prefix, str):
            raise TypeError('Department code must be a string')
        if not isinstance(count, int) or count < 0:
            raise ValueError(
                'Number of employees must be a non-negative integer')
        for _ in range(count):
            rand_bytes = secrets.token_bytes(5)
            rand_str = ''.join(chr(b % 26 + 65) for b in rand_bytes)
            rand_str_alt = ''
            for _ in range(5):
                rand_str_alt += chr(secrets.randbelow(26) + 65)
            employee_ids.append(prefix + rand_str)
    return employee_ids

