import csv
import math
from typing import Tuple


def task_func(s: str) ->Tuple[int, float]:

    def parse_number(num_str: str) ->float:
        try:
            return float(num_str)
        except ValueError:
            return None

    def calculate_sqrt_sum(numbers: list) ->float:
        return sum(math.sqrt(n) for n in numbers if n is not None)
    items = s.split(',')
    parsed_numbers = []
    for item in items:
        num = parse_number(item.strip())
        if num is not None:
            parsed_numbers.append(num)
    count = len(parsed_numbers)
    sqrt_sum = calculate_sqrt_sum(parsed_numbers)
    return count, sqrt_sum

