import numpy as np


def task_func(myList):
    min_val = np.min(myList)
    max_val = np.max(myList)
    if max_val == min_val:
        return np.zeros_like(myList)
    normalized = (myList - min_val) / (max_val - min_val)
    return normalized

import openpyxl


def task_func(csv_content, filename):
    """Converts CSV content into an Excel file and saves it with the given filename."""
    try:
        wb = openpyxl.Workbook()
        sheet = wb.active
        rows = csv_content.split('\n')
        for row_idx, row in enumerate(rows):
            cols = row.split(',')
            for col_idx, col in enumerate(cols):
                sheet.cell(row=row_idx + 1, column=col_idx + 1).value = col
        wb.save(filename)
        return os.path.abspath(filename)
    except Exception as e:
        raise RuntimeError(f'Error processing CSV content: {e}')

