import os
import random
import pandas as pd


def task_func(data_dir, csv_files=['file1.csv', 'file2.csv', 'file3.csv'],
    seed=None):
    random.seed(seed)
    file = random.choice(csv_files)
    file_path = os.path.join(data_dir, file)
    try:
        df = pd.read_csv(file_path)
    except pd.errors.EmptyDataError:
        return file, pd.DataFrame()
    n = len(df)
    if n == 0:
        return file, pd.DataFrame()
    selected_indices = random.sample(range(n), k=random.randint(1, n))
    selected_rows = df.iloc[selected_indices]
    return file, selected_rows

