import sys
import logging
from subprocess import Popen, PIPE


def task_func():
    system_info = {}
    try:
        os_name = sys.platform
        system_info['OS'] = os_name
        arch_info = sys.maxsize
        if arch_info > 2 ** 32:
            system_info['Architecture'] = '64bit'
        else:
            system_info['Architecture'] = '32bit'
        try:
            process = Popen(['free', '-m'], stdout=PIPE, stderr=PIPE)
            output, error = process.communicate()
            if error:
                raise Exception('Error executing free command')
            mem_output = output.decode().splitlines()[1].split()
            total_memory = float(mem_output[1])
            used_memory = float(mem_output[2])
            memory_usage = used_memory / total_memory * 100
            system_info['Memory Usage'] = f'{memory_usage:.2f}%'
        except:
            logging.error('Failed to get memory information')
            system_info['Memory Usage'] = 'N/A'
    except Exception as e:
        logging.error(f'Error getting system info: {e}')
        return None
    return system_info

