import sys
import struct
import os
import ctypes
import logging
from platform import architecture
logging.basicConfig(level=logging.ERROR)


def task_func():
    try:
        os_name = _get_os_name()
        arch = _get_architecture()
        usage_percent = _get_memory_usage()
        memory_str = f'{usage_percent:.2f}%'
        return {'OS': os_name, 'Architecture': arch, 'Memory Usage': memory_str
            }
    except Exception as e:
        logging.error('Error gathering system info: %s', e)
        return {'OS': 'Unknown', 'Architecture': 'Unknown', 'Memory Usage':
            'Unknown'}


def _get_os_name():
    if sys.platform.startswith('win'):
        return 'Windows'
    elif sys.platform.startswith('linux'):
        return 'Linux'
    else:
        return 'Unknown'


def _get_architecture():
    return f'{architecture()[0]}'


def _get_memory_usage_windows():


    class MEMORYSTATUSEX(ctypes.Structure):
        _fields_ = [('dwLength', ctypes.c_ulong), ('dwMemoryLoad', ctypes.
            c_ulong), ('ullTotalPhys', ctypes.c_ulonglong), ('ullAvailPhys',
            ctypes.c_ulonglong), ('ullTotalPageFile', ctypes.c_ulonglong),
            ('ullAvailPageFile', ctypes.c_ulonglong), ('ullTotalVirtual',
            ctypes.c_ulonglong), ('ullAvailVirtual', ctypes.c_ulonglong), (
            'sullAvailExtendedVirtual', ctypes.c_ulonglong)]
    mem = MEMORYSTATUSEX()
    mem.dwLength = ctypes.sizeof(MEMORYSTATUSEX)
    if not ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(mem)):
        raise ctypes.WinError()
    total = mem.ullTotalPhys
    free = mem.ullAvailPhys
    used = total - free
    return used / total * 100


def _get_memory_usage_unix():
    try:
        page_size = os.sysconf('SC_PAGE_SIZE')
        phys_pages = os.sysconf('SC_PHYS_PAGES')
        avail_pages = os.sysconf('SC_AVPHYS_PAGES')
    except (ValueError, AttributeError):
        raise RuntimeError('Unable to retrieve system memory info')
    total = page_size * phys_pages
    free = page_size * avail_pages
    used = total - free
    return used / total * 100


def _get_memory_usage():
    if sys.platform.startswith('win'):
        return _get_memory_usage_windows()
    else:
        return _get_memory_usage_unix()

