import re


def task_func(word: str):
    cleaned = re.sub('[^a-zA-Z]', '', word).lower()
    if len(cleaned) < 2:
        return []
    counts = {}
    first_occurrence = {}
    for i in range(len(cleaned) - 1):
        pair = cleaned[i:i + 2]
        counts[pair] = counts.get(pair, 0) + 1
        if pair not in first_occurrence:
            first_occurrence[pair] = i
    max_count = max(counts.values())
    candidates = [p for p, c in counts.items() if c == max_count]
    best_pair = min(candidates, key=lambda p: first_occurrence[p])
    return [(best_pair, max_count)]


def _most_common_pair_core(word: str):
    cleaned = re.sub('[^a-zA-Z]', '', word).lower()
    if len(cleaned) < 2:
        return None
    counts = {}
    first_occurrence = {}
    for i in range(len(cleaned) - 1):
        pair = cleaned[i:i + 2]
        counts[pair] = counts.get(pair, 0) + 1
        if pair not in first_occurrence:
            first_occurrence[pair] = i
    max_count = max(counts.values())
    candidates = [p for p, c in counts.items() if c == max_count]
    best_pair = min(candidates, key=lambda p: first_occurrence[p])
    return best_pair, max_count


def task_func_clean(word: str):
    result = _most_common_pair_core(word)
    return [result] if result else []


def task_func_bad(word: str):
    cleaned = re.sub('[^a-zA-Z]', '', word).lower()
    if len(cleaned) < 2:
        return []
    counts = {}
    for i in range(len(cleaned) - 1):
        pair = cleaned[i:i + 2]
        if pair in counts:
            counts[pair] += 1
        else:
            counts[pair] = 1
    max_count = 0
    best_pair = ''
    for pair, count in counts.items():
        if count > max_count:
            max_count = count
            best_pair = pair
        elif count == max_count:
            if cleaned.find(pair) < cleaned.find(best_pair):
                best_pair = pair
    return [(best_pair, max_count)]

