from typing import Dict, Any
import re


def task_func(word: str) ->Dict[str, int]:
    if not isinstance(word, str):
        raise TypeError('Input must be a string')
    sanitized_word = re.sub('[^A-Za-z]', '', word)
    if len(sanitized_word) < 2:
        return {}
    occurrences: Dict[str, int] = {}
    for i in range(len(sanitized_word) - 1):
        pair = sanitized_word[i:i + 2]
        if pair in occurrences:
            occurrences[pair] += 1
        else:
            occurrences[pair] = 1
    return occurrences

from collections import Counter


def task_func(list_of_lists):
    """Return a Counter of elements in merged list."""
    counts = {}
    for sub in list_of_lists:
        for item in sub:
            counts[item] = counts.get(item, 0) + 1
    return Counter(counts)

