import pandas as pd
from dateutil.parser import parse


def task_func(dates_str_list):
    names = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday',
        'Saturday', 'Sunday']
    monday = 0
    tuesday = 0
    wednesday = 0
    thursday = 0
    friday = 0
    saturday = 0
    sunday = 0
    for d in dates_str_list:
        try:
            w = parse(d).weekday()
        except:
            continue
        if w == 0:
            monday += 1
        elif w == 1:
            tuesday += 1
        elif w == 2:
            wednesday += 1
        elif w == 3:
            thursday += 1
        elif w == 4:
            friday += 1
        elif w == 5:
            saturday += 1
        elif w == 6:
            sunday += 1
    return pd.Series([monday, tuesday, wednesday, thursday, friday,
        saturday, sunday], index=names)

