import pandas as pd
from datetime import datetime


def task_func(dates_str_list):
    weekdays = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday',
        'Saturday', 'Sunday']
    counts = {day: (0) for day in weekdays}
    if not dates_str_list:
        return pd.Series([0] * 7, index=weekdays)
    for date_str in dates_str_list:
        try:
            date_obj = datetime.strptime(date_str, '%Y-%m-%d')
            weekday = date_obj.weekday()
            counts[weekdays[weekday]] += 1
        except ValueError:
            pass
    return pd.Series([counts[day] for day in weekdays], index=weekdays)

