import re


def task_func(log_file_path: str, keywords: list):
    if not os.path.exists(log_file_path):
        raise FileNotFoundError(f'Log file {log_file_path} does not exist.')
    with open(log_file_path, 'r') as log:
        formatted_lines = [line.strip() for line in log if any(keyword in
            line for keyword in keywords)]
    return [format_line(line) for line in formatted_lines]


def format_line(line: str):
    parts = re.split('\\s+', line, maxsplit=2)
    if len(parts) == 3:
        return f'{parts[0]:>{20}} : {parts[1]:>{20}} : {parts[2]:>{20}}'
    else:
        return f'Line format unexpected: {line}'

import pandas as pd


def task_func(csv_file, column_name=None, pattern=None, sample_size=None,
    seed=None):
    if column_name is None:
        column_name = 'data'
    if pattern is None:
        pattern = '\\d+[xX]'
    if seed is None:
        seed = 42
    df = pd.read_csv(csv_file)
    if column_name not in df.columns:
        raise KeyError(f"Column '{column_name}' not found in DataFrame")
    mask = df[column_name].astype(str).str.contains(pattern, regex=True)
    matches = df.loc[mask]
    if sample_size is None:
        return matches
    if sample_size == 0:
        return matches.iloc[0:0]
    n = min(sample_size, len(matches))
    return matches.sample(n=n, random_state=seed)

