import random


def task_func(n):
    if n < 2:
        return None
    pts = {}
    i = 0
    while i < n:
        pts[i] = random.uniform(0, 1), random.uniform(0, 1)
        i += 1
    min_dist = None
    pair = None
    keys = list(pts.keys())
    for a in keys:
        for b in keys:
            if a >= b:
                continue
            x1, y1 = pts[a]
            x2, y2 = pts[b]
            dx = x1 - x2
            dy = y1 - y2
            dist = dx * dx + dy * dy
            if min_dist is None or dist < min_dist:
                min_dist = dist
                pair = (x1, y1), (x2, y2)
    return pair

