def task_func(data_list, json_file_name):
    """Compute mean of numeric values per position and export to JSON."""
    pos_values = defaultdict(list)
    for tup in data_list:
        for idx, val in enumerate(tup[1:], start=1):
            pos_values[idx].append(val)
    results = {f'Position {i}': (sum(vals) / len(vals)) for i, vals in
        pos_values.items()}
    with open(json_file_name, 'w') as f:
        json.dump(results, f)
    return results

import numpy as np
from matplotlib import pyplot as plt
from numbers import Number
from typing import Union, Optional, Tuple


def task_func(data: np.ndarray) ->plt.Axes:
    if not isinstance(data, np.ndarray):
        raise TypeError('Input must be a NumPy array.')
    if data.size == 0:
        raise ValueError('Input array cannot be empty.')
    if not np.issubdtype(data.dtype, np.number):
        raise TypeError('Array contains non-numeric values.')
    if np.any(np.isnan(data)) or np.any(data < 0):
        raise ValueError('Array contains NaNs or negative numbers.')
    sorted_data = np.sort(data)
    n = len(sorted_data)

    def calculate_cumulative_prob(arr: np.ndarray) ->np.ndarray:
        total = arr.sum()
        if total == 0:
            return np.zeros_like(arr)
        else:
            return np.cumsum(arr) / total
    cumulative_prob = calculate_cumulative_prob(sorted_data)
    fig, ax = plt.subplots(figsize=(10, 6))
    ax.plot(cumulative_prob, marker='o', linestyle='-')
    ax.set_xlabel('Index')
    ax.set_ylabel('Cumulative Probability')
    ax.set_title('Cumulative Probability Plot')
    ax.grid(True)
    return ax

from collections import defaultdict
import re


def task_func(word: str) ->dict:
    """Return a dictionary of two-letter combinations and their counts."""
    sanitized = re.sub('[^A-Za-z]', '', word)
    pairs = {(sanitized[i] + sanitized[i + 1]) for i in range(len(sanitized
        ) - 1)}
    counts = defaultdict(int)
    for pair in pairs:
        counts[pair] += 1
    return dict(counts)

