import datetime
from zoneinfo import ZoneInfo


def task_func(date_str, from_tz, to_tz):
    try:
        date_obj = datetime.datetime.fromisoformat(date_str)
    except ValueError as e:
        raise ValueError('Invalid date string format') from e
    try:
        from_tz_obj = ZoneInfo(from_tz)
        to_tz_obj = ZoneInfo(to_tz)
    except pytz.exceptions.UnknownTimeZoneError as e:
        raise ValueError('Invalid timezone') from e
    try:
        aware_date = date_obj.replace(tzinfo=from_tz_obj)
        converted_date = aware_date.astimezone(to_tz_obj)
    except Exception as e:
        raise RuntimeError('Failed to convert timezone') from e
    return converted_date.strftime('%Y-%m-%d %H:%M:%S')

