import os
import shutil
from typing import List


def task_func(directory: str, backup_directory: str) ->List[str]:

    def get_json_files():
        json_files = []
        try:
            for filename in os.listdir(directory):
                if filename.endswith('.json'):
                    json_files.append(os.path.join(directory, filename))
        except FileNotFoundError:
            raise FileNotFoundError(f'Directory {directory} does not exist')
        return json_files

    def copy_files(files: List[str]) ->List[str]:
        backup_path = os.path.abspath(backup_directory)
        try:
            if not os.path.exists(backup_path):
                os.makedirs(backup_path, exist_ok=True)
            copied = []
            for src in files:
                dst = os.path.join(backup_path, os.path.basename(src))
                shutil.copy2(src, dst)
                copied.append(dst)
            return copied
        except Exception as e:
            raise RuntimeError(f'Failed to copy files: {e}')
    json_files = get_json_files()
    return copy_files(json_files)

