import math


def task_func(list_of_pairs):
    """
    Calculate the product of the second values in each tuple in a list of tuples.

    Args:
        list_of_pairs (list): A list of tuples, where the first element is the category and the second element is the numeric value.

    Returns:
        numpy.ndarray: A 1D numpy array containing a single element that is the product of the second values in the list of tuples.
    """
    if not isinstance(list_of_pairs, list):
        raise TypeError('Input must be a list')
    for pair in list_of_pairs:
        if not isinstance(pair, tuple) or len(pair) != 2:
            raise ValueError(
                'Each element in the input list must be a tuple with exactly two elements'
                )
    second_values = [pair[1] for pair in list_of_pairs]
    product = math.prod(second_values)
    return numpy.array([product])


