import hashlib
import uuid
import base64


def task_func(num: str, from_base: int, to_base: int, alphabet: str):
    if not num:
        raise ValueError('Invalid number format')
    if from_base < 2 or from_base > 36:
        raise ValueError('Invalid from base')
    if to_base < 2 or to_base > 36:
        raise ValueError('Invalid to base')
    try:
        decimal = int(num, from_base)
    except ValueError:
        raise ValueError('Invalid number format')
    if decimal == 0:
        converted = alphabet[0]
    else:
        converted = ''
        while decimal > 0:
            remainder = decimal % to_base
            converted = alphabet[remainder] + converted
            decimal //= to_base
    salt = uuid.uuid4().hex
    hash_object = hashlib.sha256((converted + salt).encode())
    standard_b64 = base64.b64encode(hash_object.digest()).decode()
    translation = str.maketrans(
        'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/',
        alphabet)
    encoded_hash = standard_b64.translate(translation)
    return encoded_hash, salt

