import subprocess
import os
import signal


def task_func(process_name):
    try:
        result = subprocess.check_output(['pgrep', process_name])
        pids = result.decode('utf-8').strip().split('\n')
        count = 0
        for pid in pids:
            if pid:
                os.kill(int(pid), signal.SIGTERM)
                count += 1
        return count
    except subprocess.CalledProcessError:
        return 0

