import pytz
from dateutil.parser import parse
TIME_FORMAT = '%d/%m/%y %H:%M:%S.%f'


def task_func(time_string, from_tz, to_tz):
    timezones = {'from_zone': pytz.timezone(from_tz), 'to_zone': pytz.
        timezone(to_tz)}

    def parse_time(s):
        return parse(s, dayfirst=True)
    dt = parse_time(time_string)
    localized_dt = timezones['from_zone'].localize(dt)
    converted_dt = localized_dt.astimezone(timezones['to_zone'])
    return converted_dt.strftime(TIME_FORMAT)

