from datetime import datetime
from zoneinfo import ZoneInfo


def task_func(time_string: str, from_tz: str, to_tz: str) ->str:
    try:
        dt = datetime.strptime(time_string, '%d/%m/%y %H:%M:%S.%f')
    except ValueError:
        raise ValueError(
            "time_string must be in format 'dd/mm/yy HH:MM:SS.fff'")
    try:
        src_tz = ZoneInfo(from_tz)
    except Exception:
        raise ValueError(f'Invalid source timezone: {from_tz}')
    try:
        dst_tz = ZoneInfo(to_tz)
    except Exception:
        raise ValueError(f'Invalid target timezone: {to_tz}')
    dt = dt.replace(tzinfo=src_tz)
    dt_converted = dt.astimezone(dst_tz)
    return dt_converted.strftime('%d/%m/%y %H:%M:%S.%f')

from typing import Dict, Set, List


def task_func(seq: str, letter_weight_dict: Dict[str, float]) ->str:

    def calculate_max_subsequence(s: str, weights: Dict[str, float]) ->str:
        max_total = -float('inf')
        best_subseq: List[str] = []

        def backtrack(index: int, current_seq: List[str], current_sum: float):
            nonlocal max_total, best_subseq
            if index >= len(s):
                return
            for i in range(index, len(s)):
                char = s[i]
                weight = weights.get(char, 0)
                new_sum = current_sum + weight
                if new_sum > max_total:
                    max_total = new_sum
                    best_subseq = current_seq + [char]
                backtrack(i + 1, current_seq + [char], new_sum)
        backtrack(0, [], 0)
        return ''.join(best_subseq)

    def validate_input(s: str, weights: Dict[str, float]) ->None:
        if not isinstance(s, str) or len(s) == 0:
            raise ValueError('Input string must be non-empty.')
        for char in s:
            if char not in weights:
                raise KeyError(
                    f"Character '{char}' not found in weight dictionary.")
    validate_input(seq, letter_weight_dict)
    return calculate_max_subsequence(seq, letter_weight_dict)

