import json
import os
import hashlib
import base64
from datetime import datetime


def task_func(file_path, unknown_key):

    def load_json(path):
        with open(path, 'r') as f:
            return json.load(f)

    def get_info_value(data, key):
        structure = data['A'][key]['maindata'][0]['Info']
        return structure

    def compute_hash(value):
        hashed = hashlib.sha256(value.encode()).digest()
        return base64.b64encode(hashed).decode()

    def create_output_file(prefix):
        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        filename = f'{prefix}_hashed_{timestamp}.txt'
        return os.path.join(os.getcwd(), filename)
    try:
        data = load_json(file_path)
        info_value = get_info_value(data, unknown_key)
        hashed_str = compute_hash(info_value)
        output_path = create_output_file(unknown_key)
        with open(output_path, 'w') as f:
            f.write(hashed_str)
        return output_path
    except KeyError:
        raise KeyError(f'Key {unknown_key} not found in the JSON structure')

