import logging


def task_func(nested_dict):
    agg_dict = defaultdict(int)
    try:
        for d in nested_dict.values():
            if not isinstance(d, dict):
                raise ValueError('Expected a dictionary but found {}'.
                    format(type(d)))
            for k, v in d.items():
                if k == 'ele':
                    continue
                agg_dict[k] += v
        if 'ele' in agg_dict:
            del agg_dict['ele']
        result = {}
