    max_len = max(len(v) for v in values_list)
    for v in values_list:
        if len(v) != max_len:
            raise Exception(
                "All lists in 'Value' column must have the same length")
    numeric_check = True
    for v in values_list:
        for item in v:
            if not isinstance(item, (int, float, np.number)):
                numeric_check = False
                break
        if not numeric_check:
            break
    if not numeric_check:
        raise Exception("All items in 'Value' lists must be numeric")
    values_df = pd.DataFrame(values_list, columns=[f'V{i + 1}' for i in
        range(max_len)])
    combined = pd.concat([dates.rename('Date'), values_df], axis=1)
    zscore_df = combined.copy()
    for col in values_df.columns:
        col_mean = combined[col].mean()
        col_std = combined[col].std()
        if col_std == 0 or np.isnan(col_std):
            zscore_df[col] = np.nan
        else:
            zscore_df[col] = (combined[col] - col_mean) / col_std
    fig, ax = plt.subplots()
    data_for_box = zscore_df.iloc[:, 1:].values.flatten()
    ax.boxplot(data_for_box, vert=True, patch_artist=True)
    ax.set_title('Z-Scores Over Time')
    ax.set_xlabel('Date')
    ax.set_ylabel('Z-Score')
    return zscore_df, fig

