import json
import re
import logging
logger = logging.getLogger(__name__)
logging.basicConfig(level=logging.WARNING)


def task_func(json_str, *args):
    """
    Extract URLs from a JSON string and count occurrences.

    Parameters
    ----------
    json_str : str
        JSON-encoded string containing a dictionary.
    *args : tuple
        Optional positional arguments. The first argument, if provided,
        specifies the maximum number of top URLs to return.

    Returns
    -------
    dict
        Mapping of URLs to their occurrence counts. If no URLs are found,
        an empty dictionary is returned.

    Raises
    ------
    json.decoder.JSONDecodeError
        If the input string is not valid JSON.
    """
    top_n = args[0] if args else 10
    try:
        data = json.loads(json_str)
    except json.decoder.JSONDecodeError as exc:
        logger.exception('Invalid JSON input')
        raise exc
    url_pattern = re.compile('https?://[^\\s]+|www\\.[^\\s]+')

    def extract(obj, accumulator):
        if isinstance(obj, dict):
            for value in obj.values():
                extract(value, accumulator)
        elif isinstance(obj, list):
            for item in obj:
                extract(item, accumulator)
        elif isinstance(obj, str):
            match = url_pattern.match(obj)
            if match:
                accumulator.append(match.group(0))
    urls = []
    extract(data, urls)
    if not urls:
        return {}
    counts = {}
    for url in urls:
        counts[url] = counts.get(url, 0) + 1
    if len(counts) <= top_n:
        return dict(counts)
    sorted_items = sorted(counts.items(), key=lambda x: (-x[1], x[0]))
    return dict(sorted_items[:top_n])

