import numpy as np
from sklearn.metrics import mean_squared_error


def task_func(data):
    df = pd.DataFrame(data)
    if len(df) == 0:
        return np.nan
    try:
        scores = pd.to_numeric(df['Score_String'], errors='raise')
    except ValueError:
        raise ValueError('Invalid score format in Score_String column')
    grades = df['Grade'].unique()
    if len(grades) == 0:
        return np.nan
    if len(df['Score_String']) != len(df['Grade']):
        raise ValueError('Mismatched lengths of Score_String and Grade columns'
            )
    grade_order = sorted(grades)
    grade_mapping = {grade: (i + 1) for i, grade in enumerate(grade_order)}
    encoded_grades = df['Grade'].map(grade_mapping)

    def pearson_correlation(x, y):
        n = len(x)
        sum_x = np.sum(x)
        sum_y = np.sum(y)
        sum_xy = np.sum(x * y)
        sum_x2 = np.sum(x ** 2)
        sum_y2 = np.sum(y ** 2)
        numerator = sum_xy * n - sum_x * sum_y
        denominator = np.sqrt((sum_x2 * n - sum_x ** 2) * (sum_y2 * n - 
            sum_y ** 2))
        if denominator == 0:
            return 0.0
        else:
            return numerator / denominator
    correlation = pearson_correlation(scores, encoded_grades)
    return correlation

