        return pd.NA
    try:
        scores = [float(score) for score in data['Score_String']]
    except ValueError:
        raise ValueError('Invalid score format')
    unique_grades = list(set(data['Grade']))
    grade_order = {grade: (i + 1) for i, grade in enumerate(unique_grades)}
    encoded_grades = [grade_order[grade] for grade in data['Grade']]
    if len(scores) != len(encoded_grades):
        raise ValueError('Mismatched lengths of scores and grades')
    correlation, _ = pearsonr(scores, encoded_grades)
    return correlation

