import hashlib
import os
from base64 import b64encode
import base64


def task_func(hex_str, salt_size):

    def _generate_salt(size):
        return os.urandom(size)

    def _hash_data(data):
        return hashlib.sha256(data).hexdigest()

    def _salt_and_hash(hex_str, salt_size):
        salt = _generate_salt(salt_size)
        data = bytes.fromhex(hex_str.replace('\\x', ''))
        salted_data = bytearray(salt) + data
        return b64encode(salt).decode('utf-8'), _hash_data(salted_data)
    return _salt_and_hash(hex_str, salt_size)

