import os
import logging


class FileRemover:

    def __init__(self, directory):
        self.directory = directory
        self.removed_files = []
        self.logging_handler = logging.FileHandler('jquery_removal.log')
        self.logger = logging.getLogger()
        self.logger.addHandler(self.logging_handler)
        self.logger.setLevel(logging.INFO)

    def remove_jquery_files(self):
        if not os.path.exists(self.directory):
            raise FileNotFoundError(f'Directory not found: {self.directory}')
        files = os.listdir(self.directory)
        for file in files:
            if 'jquery' in file and file.endswith('.js'):
                try:
                    os.remove(os.path.join(self.directory, file))
                    self.removed_files.append(file)
                    logging.info(f'Removed jQuery file: {file}')
                except Exception:
                    pass

    def get_removed_files(self):
        return self.removed_files


def task_func(directory):
    remover = FileRemover(directory)
    try:
        remover.remove_jquery_files()
        removed_count = len(remover.get_removed_files())
        removed_files = remover.get_removed_files()
    finally:
        if hasattr(remover, 'logger'):
            for handler in remover.logger.handlers[:]:
                handler.close()
                remover.logger.removeHandler(handler)
    return removed_count, removed_files

