import socket


def task_func(ip_addresses):
    host_map = {}

    def recurse(ips):
        if not ips:
            return
        current = ips[0]
        try:
            socket.inet_aton(current)
            try:
                host = socket.gethostbyaddr(current)[0]
            except (socket.herror, socket.gaierror):
                host = None
        except OSError:
            host = None
        host_map[current] = host
        recurse(ips[1:])
    recurse(ip_addresses)
    return host_map

