def task_func(file_path1, file_path2):

    def read_file(path):
        with open(path, 'rb') as f:
            return f.read()

    def compute_md5(data):
        md5 = hashlib.md5()
        md5.update(data)
        return md5.hexdigest()
    data1 = read_file(file_path1)
