import random


def task_func(n):
    if n < 2:
        return None
    pts = {i: (random.random(), random.random()) for i in range(n)}
    best = None
    bestd = float('inf')
    for i in range(n):
        xi, yi = pts[i]
        for j in range(i + 1, n):
            xj, yj = pts[j]
            dx = xi - xj
            dy = yi - yj
            d = dx * dx + dy * dy
            if d < bestd:
                bestd = d
                best = (xi, yi), (xj, yj)
    for i in range(n):
        for j in range(i + 1, n):
            xi, yi = pts[i]
            xj, yj = pts[j]
            dx = xi - xj
            dy = yi - yj
            _ = dx * dx + dy * dy
    return best

