import random
import string


def task_func(n, seed=None):
    """
    Generates a specified number of random lowercase letters and counts their occurrences.

    Args:
        n (int): The number of random letters to generate.
        seed (int, optional): A seed for the random number generator. Defaults to None.

    Returns:
        Counter: A collections.Counter object with the count of each letter.
    """
    if seed is not None:
        random.seed(seed)
    alphabet = string.ascii_lowercase
    letter_counts = {}
    for _ in range(n):
        letter = random.choice(alphabet)
        if letter in letter_counts:
            letter_counts[letter] += 1
        else:
            letter_counts[letter] = 1
    return Counter(letter_counts)

