class ResultDataFrame:

    def __init__(self, index, data):
        self.index = index
        self._data = data

    def __getitem__(self, key):
        return self._data[key]


def task_func(vegetable_dict):
    if not isinstance(vegetable_dict, dict):
        logger.error('Input must be a dictionary')
        raise TypeError('Input must be a dictionary')
    for k, v in vegetable_dict.items():
        if not isinstance(k, str) or not isinstance(v, str):
            logger.error('Dictionary keys and values must be strings')
            raise TypeError('Dictionary keys and values must be strings')
    veg_to_person = {v: k for k, v in vegetable_dict.items()}
    veg_list = list(veg_to_person.keys())
    if not veg_list:
        return ResultDataFrame([], {'Percentage': np.array([])})
    counts = np.random.randint(1, 11, size=len(veg_list))
    total = counts.sum()
    percentages = counts / total * 100
    return ResultDataFrame(veg_list, {'Percentage': percentages})

