import random
from collections import defaultdict
import pandas as pd


def task_func(vegetable_dict):
    if not vegetable_dict:
        return pd.DataFrame(columns=['Percentage'], index=[])
    veg_to_people = {v: k for k, v in vegetable_dict.items()}
    veg_counts = defaultdict(int)
    total_count = 0
    for veg in veg_to_people.keys():
        count = random.randint(1, 10)
        veg_counts[veg] += count
        total_count += count
    percentage_dict = {veg: (count / total_count * 100 if total_count else 
        0) for veg, count in veg_counts.items()}
    df = pd.DataFrame.from_dict(percentage_dict, orient='index', columns=[
        'Percentage'])
    return df

