import math


def task_func(elements, subset_size):
    """Return mean, median, and mode of sums of all subsets of given size."""
    sums = []

    def backtrack(start, comb):
        if len(comb) == subset_size:
            sums.append(sum(comb))
            return
        for i in range(start, len(elements)):
            backtrack(i + 1, comb + (elements[i],))
    backtrack(0, ())
    n = len(sums)
    mean_val = sum(sums) / n if n else 0
    sorted_sums = sorted(sums)
    if n % 2:
        median_val = sorted_sums[n // 2]
    else:
        median_val = (sorted_sums[n // 2 - 1] + sorted_sums[n // 2]) / 2
    freq = {}
    for s in sums:
        freq[s] = freq.get(s, 0) + 1
    mode_val = max(freq, key=lambda k: freq[k])
    return {'mean': mean_val, 'median': median_val, 'mode': mode_val}

