import statistics
from collections import Counter


def task_func(elements, subset_size):
    """Return mean, median, and mode of sums of all subsets of given size."""

    def gen_subsets(idx, current):
        if len(current) == subset_size:
            yield tuple(current)
            return
        if idx == len(elements):
            return
        yield from gen_subsets(idx + 1, current + [elements[idx]])
        yield from gen_subsets(idx + 1, current)
    sums = [sum(sub) for sub in gen_subsets(0, [])]
    mode_val = Counter(sums).most_common(1)[0][0]
    return {'mean': statistics.mean(sums), 'median': statistics.median(sums
        ), 'mode': mode_val}

from functools import reduce


def task_func(list_of_tuples):
    """Compute sum of numeric values and count of categories."""
    total = reduce(lambda acc, t: acc + t[0], list_of_tuples, 0)
    categories = {t[1] for t in list_of_tuples}
    counts = {cat: sum(1 for t in list_of_tuples if t[1] == cat) for cat in
        categories}
    return total, counts

from bs4 import BeautifulSoup
import requests
from typing import Optional
from urllib.parse import urlparse


def task_func(url: str, encoding: str='utf-8', use_lxml: bool=False
    ) ->Optional[BeautifulSoup]:
    if not url:
        return None
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
        if response.status_code != 200:
            return None
        parsed_url = urlparse(url)
        if not parsed_url.scheme or not parsed_url.netloc:
            return None
        decoded_content: str
        try:
            decoded_content = response.content.decode(encoding)
        except UnicodeDecodeError:
            return None
        parser = 'lxml' if use_lxml else 'html.parser'
        soup = BeautifulSoup(decoded_content, parser)
        return soup
    except requests.exceptions.RequestException as e:
        pass
    except Exception as e:
        pass
    return None

