import math


def task_func(points):
    """Return Euclidean distances between consecutive 2D points."""
    if not points or len(points) < 2:
        return []
    processed = [((p[0], p[0]) if len(p) == 1 else (p[0], p[1])) for p in
        points]
    return [math.hypot(x2 - x1, y2 - y1) for (x1, y1), (x2, y2) in zip(
        processed, processed[1:])]

