import numpy as np


def task_func(L):
    """
    Calculate the median of all elements in a nested list L.

    Args:
        L (list): A nested list containing numerical values.

    Returns:
        float: The median of all elements in the nested list.

    Raises:
        ValueError: If the input list is empty or contains no numeric values.
    """

    def flatten(lst):
        for el in lst:
            if isinstance(el, list):
                yield from flatten(el)
            else:
                yield el
    elements = list(flatten(L))
    if not elements:
        raise ValueError('List is empty or contains no numeric values.')
    arr = np.array(elements)
    sorted_arr = np.sort(arr)
    length = len(sorted_arr)
    if length % 2 == 1:
        return float(sorted_arr[length // 2])
    else:
        return float((sorted_arr[length // 2 - 1] + sorted_arr[length // 2]
            ) / 2)

