import numpy as np
from sklearn.preprocessing import StandardScaler


def task_func(data):
    dataframe = pd.DataFrame(data)
    numeric_columns = [column for column in dataframe.columns if dataframe[
        column].dtype in ['float64', 'int64']]
    for column in numeric_columns:
        try:
            dataframe[column] = StandardScaler().fit_transform(np.array(
                dataframe[column]).reshape(-1, 1))
        except Exception as e:
            print(f'Error scaling column {column}: {str(e)}')
    non_numeric_columns = [column for column in dataframe.columns if column
         not in numeric_columns]
    for column in non_numeric_columns:
        try:
            converted_column = pd.to_numeric(dataframe[column], errors='coerce'
                )
            if not converted_column.isna().all():
                dataframe[column] = StandardScaler().fit_transform(np.array
                    (converted_column).reshape(-1, 1))
        except Exception as e:
            print(f'Error scaling column {column}: {str(e)}')
    return dataframe

