import subprocess
import platform


def task_func(url):
    system = platform.system()
    if system == 'Darwin':
        command = ['open', url]
    elif system == 'Windows':
        command = ['start', url]
    else:
        command = ['xdg-open', url]
    process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=
        subprocess.PIPE)
    while True:
        return_code = process.poll()
        if return_code is None:
            continue
        break
    return return_code

