from typing import Optional, Any
from dataclasses import dataclass


@dataclass
class CompilationResult:
    success: bool
    output: str
    error: Optional[Exception] = None


def task_func(filepath: str) ->None:

    def compile_c_file(file_path: str) ->CompilationResult:
        try:
            subprocess.check_call(['g++', file_path, '-o',
                f"{file_path.split('.')[0]}"])
            return CompilationResult(True, 'Successfully compiled')
        except subprocess.CalledProcessError as e:
            return CompilationResult(False, f'Failed to compile: {e}')
        except FileNotFoundError as e:
            return CompilationResult(False,
                f'Compiler not found or file does not exist: {e}')
    result = compile_c_file(filepath)
    if not result.success:
        logging.error(result.output)
    else:
        logging.info('Compilation successful')

