import math


def task_func(nested_dict):
    """
    Aggregate the values of the same keys from a nested dictionary and remove the "ele" key.
    For each remaining key take the sine.

    Args:
        nested_dict (dict): A dictionary with string keys and dictionaries as values.

    Returns:
        dict: A new dictionary where each value is the sine of the corresponding value in the input dictionary.
    """
    aggregated_dict = {}
    for sub_dict in nested_dict.values():
        sub_dict.pop('ele', None)
        for k, v in sub_dict.items():
            if k not in aggregated_dict:
                aggregated_dict[k] = 0
            aggregated_dict[k] += v
    return {k: math.sin(v) for k, v in aggregated_dict.items()}

