import pandas as pd
import numpy as np
from sklearn.decomposition import PCA
from sklearn.preprocessing import StandardScaler


def task_func(data, n_components=2):
    if not isinstance(data, pd.DataFrame):
        raise ValueError('Input must be a DataFrame.')
    if len(data.columns) == 0:
        raise ValueError('DataFrame must contain at least one column.')
    try:
        data_numeric = data.apply(pd.to_numeric, errors='raise')
    except ValueError:
        raise ValueError('DataFrame contains non-numeric values.')
    if n_components > len(data.columns):
        raise ValueError('n_components cannot exceed the number of features.')
    scaler = StandardScaler()
    scaled_data = scaler.fit_transform(data_numeric)
    pca = PCA(n_components=n_components, random_state=42)
    principal_components = pca.fit_transform(scaled_data)
    return pd.DataFrame(principal_components, index=data.index)

