import os
import shutil
from pathlib import Path
from typing import List, Tuple


def task_func(source_path: str, destination_path: str) ->Tuple[str, List[str]]:

    def get_files_in_directory(directory: Path) ->List[Path]:
        files = []
        for entry in directory.iterdir():
            if entry.is_file():
                files.append(entry)
        return files

    def copy_files(files: List[Path], dest: Path):
        for file in files:
            shutil.copy(file, dest)
    source_path_obj = Path(source_path).resolve()
    destination_path_obj = Path(destination_path).resolve()
    if not source_path_obj.exists():
        raise ValueError(f'Source path {source_path} does not exist.')
    if not source_path_obj.is_dir():
        raise NotADirectoryError(
            f'Source path {source_path} is not a directory.')
    if not destination_path_obj.parent.exists():
        raise FileNotFoundError(
            f'Parent of destination path {destination_path} does not exist.')
    os.makedirs(destination_path_obj, exist_ok=True)
    files = get_files_in_directory(source_path_obj)
    copy_files(files, destination_path_obj)
    return source_path_obj.name, [file.name for file in files]

