import os
from pathlib import Path


def task_func(filename: str, dest_dir: str) ->str:

    def _create_directory(path):
        try:
            os.makedirs(str(path))
        except FileExistsError:
            pass

    def _copy_file(src, dst):
        with open(src, 'rb') as f_in, open(dst, 'wb') as f_out:
            f_out.write(f_in.read())

    def _clear_file_contents(file_path):
        with open(file_path, 'w') as f:
            pass
    dest_dir = Path(dest_dir)
    filename = Path(filename)
    if not dest_dir.exists():
        _create_directory(dest_dir)
    src_path = str(filename.resolve())
    dst_path = os.path.join(str(dest_dir), os.path.basename(src_path))
    if os.path.abspath(src_path) == os.path.abspath(dst_path):
        raise OSError('Source and destination are the same')
    _copy_file(src_path, dst_path)
    _clear_file_contents(src_path)
    return dst_path

