import matplotlib.pyplot as plt


def task_func(time_strings):

    def parse_datetime(s):
        try:
            return datetime.datetime.strptime(s, '%d/%m/%y %H:%M:%S.%f')
        except ValueError:
            raise ValueError(f'Invalid datetime string: {s}')

    def compute_differences(dates):
        differences = []
        for i in range(1, len(dates)):
            diff = dates[i] - dates[i - 1]
            total_sec = diff.total_seconds()
            if total_sec >= 1:
                differences.append(total_sec)
            else:
                differences.append(0)
        return differences
    parsed_dates = [parse_datetime(s) for s in time_strings]
    diffs = compute_differences(parsed_dates)
    fig, ax = plt.subplots()
    ax.bar(range(len(diffs)), diffs)
    ax.set_xticks([])
    ax.set_yticks([])
    return ax

