def task_func(letters: list, repetitions: int) ->dict:
    """Count frequency of each letter after repeating the list."""
    if not letters or repetitions <= 0:
        return {}
    counts = {}
    for letter in letters:
        repeated_letters = [letter] * repetitions
        for l in repeated_letters:
            counts[l] = counts.get(l, 0) + 1
    return counts

