import secrets
import re


def task_func(text: str, seed: int) ->str:
    """Generates a secure password based on the structure of the input text."""
    if not text:
        raise ValueError('Input text cannot be empty.')

    def generate_char(match):
        char = match.group()
        if char.isalpha():
            return secrets.choice('abcdefghijklmnopqrstuvwxyz')
        elif char.isdigit():
            return str(secrets.randbelow(10))
        elif char.isspace():
            return secrets.choice([secrets.choice('0123456789'), secrets.
                choice('abcdefghijklmnopqrstuvwxyz')])
        else:
            return char
    processed = re.sub('(\\w|\\d| |.)', generate_char, text)
    return processed

