import secrets
from typing import Optional


def task_func(text: str, seed: Optional[int]=None) ->str:
    if not text:
        raise ValueError('text cannot be empty.')

    def replace_char(char: str) ->str:
        if char.isalpha():
            return chr(secrets.randbelow(26) + ord('a'))
        elif char.isdigit():
            return str(secrets.randbelow(10))
        elif char == ' ':
            return secrets.choice([chr(secrets.randbelow(26) + ord('a')),
                str(secrets.randbelow(10))])
        else:
            return char
    if seed is not None:
        secrets.SystemRandom().seed(seed)
    password = ''.join(map(replace_char, text))
    return password

