def task_func(s: str) ->np.ndarray:
    words = re.findall('\\w+', s)
    word_counts = {}
    for word in words:
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1
    all_words = set(word_counts.keys())
    for sentence in SENTENCES:
        sentence_words = re.findall('\\w+', sentence)
        for word in sentence_words:
            if word not in word_counts:
                word_counts[word] = 0
    feature_list = list(word_counts.keys())
    features = []
    for word in feature_list:
        features.append(word_counts.get(word, 0))
    return np.array(features)

