import binascii
import gzip
import io


def task_func(compressed_hex):

    def decompress_bytes(data):
        try:
            with gzip.GzipFile(fileobj=io.BytesIO(data)) as f:
                return f.read()
        except gzip.BadGzipFile as e:
            raise ValueError(f'Error during decompression: {str(e)}')
    hex_to_bytes = binascii.unhexlify(compressed_hex)
    bytes_to_str = decompress_bytes(hex_to_bytes).decode('utf-8')
    return bytes_to_str

