        elif w == 2:
            wednesday += 1
        elif w == 3:
            thursday += 1
        elif w == 4:
            friday += 1
        elif w == 5:
            saturday += 1
        elif w == 6:
            sunday += 1
    return pd.Series([monday, tuesday, wednesday, thursday, friday,
        saturday, sunday], index=names)

