import random
from typing import List, Optional


def task_func(numbers: Optional[List[int]]=None) ->float:
    if numbers is None:
        numbers = list(range(1, 11))

    def sum_of_abs_diffs(permutation: List[int]) ->int:
        return sum(abs(a - b) for a, b in zip(permutation, permutation[1:]))
    perms = itertools.permutations(numbers)
    shuffled_perms = (tuple(random.sample(p, len(p))) for p in perms)
    total_sum = 0
    count = 0
    for perm in shuffled_perms:
        total_sum += sum_of_abs_diffs(perm)
        count += 1
    return total_sum / count if count > 0 else 0.0

