import os
from pathlib import Path
import tarfile
from typing import Union, List, Optional


def task_func(directory: str, backup_dir: str='/path/to/backup') ->Union[
    str, str]:

    def get_log_files() ->List[Path]:
        dir_path = Path(directory)
        if not dir_path.exists():
            raise FileNotFoundError(f"Directory '{directory}' not found.")
        return list(dir_path.glob('*.log'))

    def create_backup(logs: List[Path]) ->Optional[str]:
        backup_path = Path(backup_dir) / 'logs_backup.tar.gz'
        try:
            with tarfile.open(str(backup_path), 'w:gz') as tar:
                for file in logs:
                    tar.add(file)
            return str(backup_path)
        except Exception as e:
            raise RuntimeError(f'Failed to create backup: {e}')

    def delete_logs(logs: List[Path]) ->None:
        try:
            for file in logs:
                if file.exists():
                    file.unlink()
        except Exception as e:
            raise RuntimeError(f'Failed to delete log files: {e}')
    log_files = get_log_files()
    if not log_files:
        return 'No logs found to backup'
    backup_file = create_backup(log_files)
    delete_logs(log_files)
    return backup_file

