import os
from typing import Dict
import re
from collections import defaultdict


def task_func(folder_path: str) ->Dict[str, int]:
    ip_pattern = re.compile('\\b(?:\\d{1,3}\\.){3}\\d{1,3}\\b')
    file_counter: Dict[str, int] = defaultdict(int)

    def is_log_file(filename: str) ->bool:
        return filename.lower().endswith('.log')
    try:
        for root, dirs, files in os.walk(folder_path):
            for file in files:
                if is_log_file(file):
                    with open(os.path.join(root, file), 'r', errors='ignore'
                        ) as f:
                        content = f.read()
                        matches = ip_pattern.findall(content)
                        for match in matches:
                            file_counter[match] += 1
    except Exception as e:
        raise RuntimeError(f'Error processing directory: {e}') from e
    return dict(file_counter)

