from ipaddress import IPv4Network
logging.basicConfig(level=logging.INFO)


def task_func(ip_range):
    try:
        network = IPv4Network(ip_range, strict=False)
        results = {}
        for ip in network:
            try:
                command = ['ping', '-c', '1', str(ip)]
                result = subprocess.check_output(command, stderr=subprocess
                    .PIPE)
                if result == b'' or 'bytes=' in result.decode():
                    results[str(ip)] = True
                    logging.info(f'IP {ip} is active.')
                else:
                    results[str(ip)] = False
                    logging.info(f'IP {ip} is inactive.')
            except subprocess.CalledProcessError as e:
                results[str(ip)] = False
                logging.error(f'Error pinging {ip}: {e}')
            except Exception as e:
                results[str(ip)] = False
                logging.exception(
                    f'An unexpected error occurred while pinging {ip}: {e}')
        return results
    except ValueError as e:
        logging.error(f'Invalid IP range: {ip_range}. Error: {e}')
        return {}
    except Exception as e:
        logging.exception(f'An unexpected error occurred: {e}')
        return {}

