import numpy as np
import matplotlib.pyplot as plt
import logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)


class SimpleDataFrame:

    def __init__(self, data, columns):
        self._data = np.array(data, dtype=float)
        self._columns = list(columns)

    @property
    def shape(self):
        return self._data.shape

    @property
    def columns(self):
        return self._columns

    def __getitem__(self, key):
        if key not in self._columns:
            raise KeyError(f'Column {key!r} not found')
        idx = self._columns.index(key)
        return self._data[:, idx]

    def __setitem__(self, key, value):
        if key not in self._columns:
            raise KeyError(f'Column {key!r} not found')
        idx = self._columns.index(key)
        self._data[:, idx] = value


def task_func(data):
    if not isinstance(data, np.ndarray):
        raise TypeError('Input must be a NumPy array')
    if data.ndim != 2 or data.shape[1] != 8:
        raise ValueError('Input array must have shape (n, 8)')
    if not np.issubdtype(data.dtype, np.number):
        raise TypeError('Input array must contain numeric values')
    min_vals = data.min(axis=1, keepdims=True)
    max_vals = data.max(axis=1, keepdims=True)
    denom = max_vals - min_vals
    denom[denom == 0] = 1.0
    normalized = (data - min_vals) / denom
    averages = normalized.mean(axis=1)
    combined = np.column_stack((normalized, averages))
    column_names = [f'Col{i + 1}' for i in range(8)] + ['Average']
    df = SimpleDataFrame(combined, column_names)
    fig, ax = plt.subplots()
    ax.plot(averages)
    return df, ax

