from collections import Counter


def task_func(elements, subset_size):
    n = len(elements)
    if subset_size > n or subset_size <= 0:
        return Counter()
    result = Counter()

    def backtrack(start, current_sum, depth):
        if depth == subset_size:
            result[current_sum] += 1
            return
        for i in range(start, n):
            backtrack(i + 1, current_sum + elements[i], depth + 1)
    backtrack(0, 0, 0)
    return result

