import logging
from collections import Counter
logging.basicConfig(level=logging.WARNING)
logger = logging.getLogger(__name__)


def task_func(elements, subset_size):
    """
    Return a Counter mapping each possible sum of all subsets of the given
    size to the number of times that sum occurs.
    """
    if not isinstance(elements, tuple):
        logger.error('elements must be a tuple')
        raise TypeError('elements must be a tuple')
    if not isinstance(subset_size, int):
        logger.error('subset_size must be an integer')
        raise TypeError('subset_size must be an integer')
    if subset_size < 0:
        logger.error('subset_size must be non-negative')
        raise ValueError('subset_size must be non-negative')
    n = len(elements)
    if subset_size > n or n == 0:
        return Counter()
    result = Counter()

    def backtrack(start, depth, current_sum):
        if depth == subset_size:
            result[current_sum] += 1
            return
        for i in range(start, n - (subset_size - depth) + 1):
            backtrack(i + 1, depth + 1, current_sum + elements[i])
    backtrack(0, 0, 0)
    return result

