def task_func(data, cols, percentage):
    corr_combinations = []
    num_columns = len(cols)
    column_indices = {col: idx for idx, col in enumerate(cols)}
    data_array = np.array(data)
    for i in range(num_columns):
        for j in range(i + 1, num_columns):
            col1 = cols[i]
            col2 = cols[j]
            corr = np.corrcoef(data_array[:, i], data_array[:, j])[0, 1]
            abs_corr = abs(corr)
            if abs_corr > percentage:
                corr_combinations.append((col1, col2))
    return corr_combinations

