def task_func(request):

    def build_response(code, reason, body, length=None):
        hdr = f'HTTP/1.1 {code} {reason}\r\n'
        if length is not None:
            hdr += f'Content-Length: {length}\r\n'
        hdr += '\r\n'
        return hdr + body
    parts = request.split()
    if len(parts) != 3 or parts[0] != 'GET' or not parts[1].startswith('/'
        ) or parts[2] != 'HTTP/1.1':
        return build_response('400', 'BAD REQUEST', 'Bad Request')
    path = parts[1][1:]
    if not path:
        return build_response('400', 'BAD REQUEST', 'Bad Request')
    if not os.path.isfile(path):
        return build_response('404', 'NOT FOUND', 'File Not Found')
    try:
        with open(path, 'rb') as f:
            data = f.read()
        return build_response('200', 'OK', data.decode('utf-8'), len(data))
    except Exception:
        return build_response('500', 'INTERNAL SERVER ERROR',
            'Internal Server Error')

