from datetime import datetime, timedelta
import dateutil.parser


def task_func(date_str):
    """
    Get the next business day after a given date string in 'yyyy-mm-dd' format.
    Business days are Monday to Friday.
    """
    date_obj = dateutil.parser.parse(date_str)
    current_day = date_obj + timedelta(days=1)
    while True:
        if current_day.weekday() < 5:
            return datetime.combine(current_day.date(), datetime.min.time())
        current_day += timedelta(days=1)

