import re
import logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)


def task_func(url):
    if not isinstance(url, str):
        logger.warning('URL is not a string')
        return None
    query_part = None
    try:
        query_part = re.search('\\?(.*)', url).group(1)
    except AttributeError:
        logger.warning('No query string found')
        return None
    params = {}
    for pair in query_part.split('&'):
        if '=' in pair:
            key, value = pair.split('=', 1)
            params[key] = value
    q_value = params.get('q')
    if not q_value:
        logger.warning("'q' parameter missing")
        return None
    try:
        decoded_bytes = bytes.fromhex(q_value)
        decoded_str = decoded_bytes.decode('utf-8')
        return decoded_str
    except (ValueError, UnicodeDecodeError):
        logger.warning('First decoding attempt failed')
    try:
        decoded_bytes = bytes.fromhex(q_value)
        decoded_str = decoded_bytes.decode('utf-8')
        return decoded_str
    except (ValueError, UnicodeDecodeError):
        logger.warning('Second decoding attempt failed')
    return None

