def task_func(python_version='3.8', path_to_append='/path/to/whatever'):

    def switch_python_version(version):
        command = ['pyenv', 'global', version]
        try:
            subprocess.run(command, check=True)
        except subprocess.CalledProcessError as e:
            raise RuntimeError(f'Failed to switch Python version: {e}')

    def append_path(path):
        sys.path.append(path)
    switch_python_version(python_version)
    append_path(path_to_append)
    return python_version

