import pandas as pd
from pandas.api.types import is_numeric_dtype


def task_func(df: pd.DataFrame, age, weight):
    if df.empty:
        raise Exception('Input DataFrame is empty')
    if 'Age' not in df.columns or 'Weight' not in df.columns:
        raise KeyError('Required columns missing')
    if not is_numeric_dtype(df['Age']) or not is_numeric_dtype(df['Weight']):
        raise Exception('Non-numeric values detected')
    filtered = df[(df['Age'] < age) & (df['Weight'] > weight)]
    if filtered.empty:
        return pd.DataFrame(columns=df.columns)
    standardized = filtered.apply(lambda col: (col - col.mean()) / col.std(
        ddof=0))
    return standardized

