import pandas as pd
from sklearn.preprocessing import StandardScaler


def task_func(df, age, weight):
    if df.empty:
        raise Exception('Input DataFrame is empty')
    try:
        age_col = df['Age']
        weight_col = df['Weight']
    except KeyError:
        raise
    if not (age_col.dtype.kind in 'biufc' and weight_col.dtype.kind in 'biufc'
        ):
        raise Exception('Non-numeric values in Age or Weight')
    filtered = df[(age_col < age) & (weight_col > weight)]
    if filtered.empty:
        return filtered
    scaler = StandardScaler()
    scaled = scaler.fit_transform(filtered)
    return pd.DataFrame(scaled, columns=filtered.columns, index=filtered.index)

