import os
BACKUP_DIR = '/tmp/backup'


def task_func(directory):
    if not os.path.exists(BACKUP_DIR):
        return (
            'Backup directory /tmp/backup does not exist. Cannot rollback update.'
            )
    if not os.listdir(BACKUP_DIR):
        return 'No backups found in /tmp/backup. Cannot rollback update.'
    shutil.rmtree(directory)
    backup_source = os.path.join(BACKUP_DIR, os.listdir(BACKUP_DIR)[0])
    shutil.copytree(backup_source, directory)
    return directory

