import json
import random
import os


def task_func(LETTERS, n):
    if not isinstance(LETTERS, list):
        raise TypeError('LETTERS must be a list')
    if not isinstance(n, int):
        raise TypeError('n must be an integer')
    if n <= 0:
        raise ValueError('n must be a positive integer')
    filename = f'letter_combinations_{random.randint(0, 100)}.json'
    combinations = []

    def generate_combinations(current_combination, length):
        if length == 0:
            combinations.append(current_combination)
            return
        for letter in LETTERS:
            generate_combinations(current_combination + [letter], length - 1)
    generate_combinations([], n)
    letter_counts = {}
    for combination in combinations:
        for letter in combination:
            letter_counts[letter] = letter_counts.get(letter, 0) + 1
    with open(filename, 'w') as f:
        json.dump(letter_counts, f, indent=4)
    return filename

