import logging


def task_func(L):
    if not isinstance(L, list):
        raise TypeError('Input must be a list')

    def _flatten(lst):
        for item in lst:
            if isinstance(item, list):
                yield from _flatten(item)
            else:
                if not isinstance(item, (int, float)):
                    raise TypeError('All elements must be numeric')
                yield item
    flat_list = list(_flatten(L))
    if not flat_list:
        raise ValueError('List is empty')
    flat_list.sort()
    n = len(flat_list)
    mid = n // 2
    if n % 2 == 1:
        median = float(flat_list[mid])
    else:
        median = (flat_list[mid - 1] + flat_list[mid]) / 2.0
    logging.getLogger(__name__).debug('Computed median: %s', median)
    return median

