import pandas as pd


def task_func(word: str) ->pd.DataFrame:

    def get_position(char: str) ->int:
        return ord(char) - ord('a') + 1

    def validate_input(w: str) ->None:
        if w and not w.isalpha():
            raise ValueError('Input word must be alphabetic characters only.')
        if w and not w.islower():
            raise ValueError('Input word must be in lowercase letters.')

    def process_word(w: str):
        letters = list(w)
        positions = [get_position(c) for c in letters]
        return letters, positions
    validate_input(word)
    letters, positions = process_word(word)
    return pd.DataFrame({'Letter': letters, 'Position': positions})

