import string


def task_func(n, pattern):
    if n == 0:
        return ''
    m = re.search('\\[([^\\]]+)\\]', pattern)
    if m:
        char_class = m.group(1)
        allowed = ''
        i = 0
        while i < len(char_class):
            if i + 2 < len(char_class) and char_class[i + 1] == '-':
                start = char_class[i]
                end = char_class[i + 2]
                allowed += ''.join(chr(c) for c in range(ord(start), ord(
                    end) + 1))
                i += 3
            else:
                allowed += char_class[i]
                i += 1
    else:
        allowed = string.ascii_letters
    result = ''.join(random.choice(allowed) for _ in range(n))
    if re.match(pattern, result):
        return result
    for _ in range(10):
        result = ''.join(random.choice(allowed) for _ in range(n))
        if re.match(pattern, result):
            return result
    return ''

