import json, hashlib, blake3


def task_func(req_data):

    def _to_json(d):
        return json.dumps(d)

    def _blake3_hex(s):
        return blake3.blake3(s.encode('utf-8')).hexdigest()

    def _md5_hex(h):
        return hashlib.md5(h.encode('utf-8')).hexdigest()
    json_str = _to_json(req_data)
