import pathlib
import re


def task_func(dir_path: str) ->dict:
    """Search for the word 'error' in all .txt files under dir_path.

    Returns a dictionary mapping relative file paths to the count of
    occurrences of the word 'error', case‑insensitively.
    """
    base = pathlib.Path(dir_path)
    if not base.is_dir():
        raise ValueError('Specified directory does not exist.')

    def _read_file(path: pathlib.Path) ->str:
        with path.open('r', encoding='utf-8', errors='ignore') as f:
            return f.read()

    def _count_error(text: str) ->int:
        return len(re.findall('\\berror\\b', text, re.IGNORECASE))
    result = {p.relative_to(base).as_posix(): _count_error(_read_file(p)) for
        p in base.rglob('*.txt')}
    return result

