import os
import re


def task_func(dir_path):
    if not os.path.isdir(dir_path):
        raise ValueError
    pattern = re.compile('\\berror\\b', re.IGNORECASE)

    def _scan(path):
        for entry in os.scandir(path):
            if entry.is_dir():
                yield from _scan(entry.path)
            elif entry.is_file() and entry.name.lower().endswith('.txt'):
                yield entry.path
    files = list(_scan(dir_path))
    return {os.path.normpath(os.path.relpath(f, dir_path)): sum(1 for _ in
        pattern.finditer(open(f, encoding='utf-8', errors='ignore').read())
        ) for f in files}

