import math


def task_func(data):
    s = data['Score_String']
    g = data['Grade']
    if len(s) < 2:
        return float('nan')
    if len(s) != len(g):
        raise ValueError('Mismatched lengths of scores and grades')
    try:
        scores = [float(x) for x in s]
    except ValueError:
        raise ValueError('Invalid score format')
    uniq_grades = set(g)
    mapping = {grade: idx for idx, grade in enumerate(sorted(uniq_grades))}
    grades = [mapping[grade] for grade in g]
    n = len(scores)
    sum_s = sum(scores)
    mean_s = sum_s / n
    sum_g = sum(grades)
    mean_g = sum_g / n
    numerator = sum((scores[i] - mean_s) * (grades[i] - mean_g) for i in
        range(n))
    sum_s_squared = sum((val - mean_s) ** 2 for val in scores)
    sum_g_squared = sum((val - mean_g) ** 2 for val in grades)
    if sum_s_squared == 0 or sum_g_squared == 0:
        return float('nan')
    denominator = math.sqrt(sum_s_squared * sum_g_squared)
    corr = numerator / denominator if denominator != 0 else float('nan')
    return corr

