import numpy as np


def task_func(target_value='332', array=None):
    if array is None:
        array = globals().get('ARRAY', np.array([]))
    indices = np.where(array == target_value)[0]
    if len(indices) == 0:
        return 'N/A', 'N/A', 'N/A', 'N/A'
    mean = float(np.mean(indices))
    if len(indices) < 2:
        variance = 'N/A'
    else:
        variance = float(np.var(indices, ddof=0))
    if len(indices) < 3:
        skewness = 'N/A'
    else:
        n = len(indices)
        m = np.mean(indices)
        s = np.std(indices, ddof=0)
        skewness = float(np.sum((indices - m) ** 3) / n / s ** 3)
    if len(indices) < 4:
        kurtosis = 'N/A'
    else:
        n = len(indices)
        m = np.mean(indices)
        s = np.std(indices, ddof=0)
        kurtosis = float(np.sum((indices - m) ** 4) / n / s ** 4 - 3)
    return mean, variance, skewness, kurtosis

