import json
from collections import Counter
import ast


def task_func(file_pointer):
    """Reads JSON data from file pointer and counts key frequencies."""
    data = json.load(file_pointer)
    key_counter = Counter()

    def process_item(item):
        nonlocal key_counter
        try:
            if isinstance(item, str):
                evaluated = ast.literal_eval(item)
                if isinstance(evaluated, dict):
                    key_counter.update(evaluated.keys())
            elif isinstance(item, dict):
                key_counter.update(item.keys())
        except (ValueError, TypeError):
            pass
    for item in data:
        process_item(item)
    return key_counter

