import math


def task_func(x):
    items = list(x.items())
    all_pairs = []
    for i in range(len(items)):
        for j in range(i + 1, len(items)):
            pair = items[i][0], items[j][0]
            sum_cos = math.cos(items[i][1]) + math.cos(items[j][1])
            all_pairs.append((pair, sum_cos))
    max_sum = max([s for p, s in all_pairs])
    candidate_pairs = [p for p, s in all_pairs if s == max_sum]
    return tuple(sorted(candidate_pairs[0]))

