import re
from sklearn.cluster import KMeans
from sklearn.feature_extraction.text import CountVectorizer


def task_func(df):
    if df is None:
        raise TypeError
    if not hasattr(df, 'columns'):
        raise TypeError
    if df.empty:
        return []
    required = {'Title', 'Content'}
    if not required.issubset(df.columns):
        raise KeyError
    pattern = re.compile('(how|what)', re.IGNORECASE)
    title_mask = df['Title'].apply(lambda t: bool(pattern.search(t)))
    filtered_df = df[title_mask]
    if filtered_df.empty:
        return []
    content_dict = {idx: row['Content'] for idx, row in filtered_df.iterrows()}
    contents = list(content_dict.values())
    vectorizer = CountVectorizer()
    X = vectorizer.fit_transform(contents)
    kmeans = KMeans(n_clusters=2, random_state=0, n_init=10)
    kmeans.fit(X)
    labels_tuple = tuple(kmeans.labels_)
    return list(labels_tuple)

