import numpy as np


def task_func(arr):
    """Reverse dot-separated words in each string of a numpy array."""
    out = []
    for s in arr:
        if '.' in s:
            out.append('.'.join(reversed(s.split('.'))))
        else:
            out.append(s)
    return np.array(out)

