import os
import re
import fnmatch
from pathlib import Path


def task_func(pattern: str, directory: str, extensions: list):
    matched = []
    for root, _, files in os.walk(directory):
        for name in files:
            if any(fnmatch.fnmatch(name, ext) for ext in extensions):
                path = os.path.join(root, name)
                try:
                    with open(path, 'r', encoding='utf-8') as f:
                        content = f.read()
                    if re.search(pattern, content, re.IGNORECASE):
                        matched.append(os.path.abspath(path))
                except Exception:
                    pass
    return matched


def task_func_set(pattern: str, directory: str, extensions: list):
    result = set()
    for root, _, files in os.walk(directory):
        for name in files:
            if any(fnmatch.fnmatch(name, ext) for ext in extensions):
                path = os.path.join(root, name)
                try:
                    with open(path, 'r', encoding='utf-8') as f:
                        content = f.read()
                    if re.search(pattern, content, re.IGNORECASE):
                        result.add(os.path.abspath(path))
                except Exception:
                    pass
    return result


def _search_in_file(path: str, pattern: str):
    try:
        with open(path, 'r', encoding='utf-8') as f:
            return re.search(pattern, f.read(), re.IGNORECASE) is not None
    except Exception:
        return False


def task_func_isolated(pattern: str, directory: str, extensions: list):
    matches = []
    for root, _, files in os.walk(directory):
        for name in files:
            if any(fnmatch.fnmatch(name, ext) for ext in extensions):
                full_path = os.path.join(root, name)
                if _search_in_file(full_path, pattern):
                    matches.append(os.path.abspath(full_path))
    return matches


def task_func_bad(pattern: str, directory: str, extensions: list):
    result = []
    for root, _, files in os.walk(directory):
        for name in files:
            if fnmatch.fnmatch(name, extensions[0]) or fnmatch.fnmatch(name,
                extensions[1]) or fnmatch.fnmatch(name, extensions[2]):
