import pandas as pd
import numpy as np


def task_func(data, columns=None, fill_missing=None, num_range=None, seed=None
    ):
    if columns is None:
        columns = ['Name', 'Age', 'Occupation']
    if fill_missing is None:
        fill_missing = False
    if num_range is None:
        num_range = 0, 100
    if seed is not None:
        np.random.seed(seed)
    rows = []
    for tup in data:
        row = list(tup) + [None] * (len(columns) - len(tup))
        rows.append(row[:len(columns)])
    df = pd.DataFrame(rows, columns=columns)
    if fill_missing:
        for col in df.columns:
            non_none = df[col].dropna()
            if non_none.empty:
                continue
            if all(isinstance(v, (int, float)) for v in non_none):
                mask = df[col].isna()
                if mask.any():
                    rng_min, rng_max = num_range
                    random_vals = np.random.randint(rng_min, rng_max + 1,
                        size=mask.sum())
                    df.loc[mask, col] = random_vals
    return df

