import os


def task_func(my_path: str) ->str:
    file_size_data: Dict[str, int] = {}
    directory_path = Path(my_path)
    if not directory_path.exists():
        raise FileNotFoundError(
            f"The directory '{directory_path}' does not exist.")
    try:
        for root, _, files in os.walk(directory_path):
            for file in files:
                file_path = os.path.join(root, file)
                file_size = os.path.getsize(file_path)
                if file in file_size_data:
                    file_size_data[file] += file_size
                else:
                    file_size_data[file] = file_size
        csv_file_path = directory_path / 'file_sizes.csv'
        with open(csv_file_path, 'w', newline='', encoding='utf-8') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow(['File Name', 'Size'])
            for file_name, size in file_size_data.items():
                writer.writerow([file_name, size])
    except Exception as e:
        raise RuntimeError(
            f"An error occurred while processing directory '{directory_path}': {str(e)}"
            )
    return str(csv_file_path)

