import pandas as pd
import numpy as np
from scipy.stats import pearsonr
from typing import Dict, Any
from pandas.api.types import is_numeric_dtype


def task_func(df: pd.DataFrame, dct: Dict[Any, Any]) ->pd.DataFrame:
    if not isinstance(df, pd.DataFrame):
        raise ValueError('Input must be a DataFrame')
    if not all(is_numeric_dtype(df[col]) for col in df.columns):
        raise ValueError(
            'DataFrame must contain numeric data for Pearson correlation')
    try:
        df_replaced = df.replace(dct)
        corr_matrix = np.zeros((len(df.columns), len(df.columns)))
        columns = df.columns
        for i in range(len(columns)):
            for j in range(len(columns)):
                if i == j:
                    corr_matrix[i, j] = 1.0
                else:
                    try:
                        corr, _ = pearsonr(df_replaced[columns[i]],
                            df_replaced[columns[j]])
                        corr_matrix[i, j] = corr
                    except Exception as e:
                        corr_matrix[i, j] = np.nan
        return pd.DataFrame(corr_matrix, index=columns, columns=columns)
    except Exception as e:
        raise ValueError(f'Error processing DataFrame: {str(e)}')

