import pandas as pd
import numpy as np


def task_func(df, dct):

    def replace_values(dataframe, replacement_map):
        for col in dataframe.columns:
            if isinstance(dataframe[col].dtype, pd.CategoricalDtype):
                dataframe[col] = dataframe[col].cat.codes
            else:
                dataframe[col] = dataframe[col].replace(replacement_map)
        return dataframe

    def calculate_correlations(dataframe):
        values = dataframe.values
        correlations = np.corrcoef(values, rowvar=False)
        return pd.DataFrame(correlations, index=dataframe.columns, columns=
            dataframe.columns)
    if not isinstance(df, pd.DataFrame):
        raise ValueError('Input must be a DataFrame')
    df = replace_values(df, dct)
    correlation_matrix = calculate_correlations(df)
    return correlation_matrix

