import os
import time
import subprocess
from pathlib import Path


def task_func(script_path: str):
    """Run all Python scripts in the given directory and return their execution times."""
    dir_path = Path(script_path)
    if not dir_path.is_dir():
        return {}
    scripts = list(dir_path.glob('*.py'))
    if not scripts:
        return {}
    times = {}
    for script in scripts:
        start = time.perf_counter()
        subprocess.run(['python', str(script)], capture_output=True, text=
            True, check=False)
        times[script.name] = time.perf_counter() - start
    return times

