import pathlib
import runpy
import datetime
import logging


def task_func(test_dir):
    try:
        dir_path = pathlib.Path(test_dir)
    except Exception:
        return {}
    if not dir_path.is_dir():
        return {}
    py_files = [p for p in dir_path.iterdir() if p.is_file() and p.suffix ==
        '.py']
    if not py_files:
        return {}
    execution_times = {}
    for py_file in py_files:
        start_time = datetime.datetime.now()
        try:
            runpy.run_path(str(py_file))
        except Exception:
            pass
        end_time = datetime.datetime.now()
        elapsed = (end_time - start_time).total_seconds()
        execution_times[py_file.name] = elapsed
    return execution_times

